// lightFilter.cpp:250-258.
function _GetShaderIdAttrName(renderContext: string): string {
  if (renderContext === '') {
    return UsdLuxTokens.lightFilterShaderId
  }
  // SdfPath::JoinIdentifier(renderContext, lightFilterShaderId).
  return `${renderContext}:${UsdLuxTokens.lightFilterShaderId}`
}

